use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Convert path dependencies to workspace format using metadata"] pub fn convert_to_workspace_deps_with_metadata (deps_metadata : & HashMap < String , DependencyMetadata > , submodules_path : & Path ,) -> HashMap < String , Value > { let mut workspace_deps = HashMap :: new () ; for (name , metadata) in deps_metadata { if let Some (table) = metadata . value . as_table () { if table . contains_key ("path") { let mut new_table = toml :: Table :: new () ; if let Some (path_val) = table . get ("path") . and_then (| v | v . as_str ()) { let relative_path = if path_val . contains ("/submodules/") { let parts : Vec < & str > = path_val . split ("/submodules/") . collect () ; format ! ("../submodules/{}" , parts [1]) } else { format ! ("wrapped-{}" , name) } ; new_table . insert ("path" . to_string () , Value :: String (relative_path)) ; } if let Some (default_features) = metadata . default_features { new_table . insert ("default-features" . to_string () , Value :: Boolean (default_features)) ; } if ! metadata . features . is_empty () { let features_array = metadata . features . iter () . map (| f | Value :: String (f . clone ())) . collect () ; new_table . insert ("features" . to_string () , Value :: Array (features_array)) ; } if metadata . optional { new_table . insert ("optional" . to_string () , Value :: Boolean (true)) ; } workspace_deps . insert (name . clone () , Value :: Table (new_table)) ; } else { workspace_deps . insert (name . clone () , metadata . value . clone ()) ; } } else { workspace_deps . insert (name . clone () , metadata . value . clone ()) ; } } workspace_deps }